using marble_physics::Mem;
using marble_physics::PLAYER;
using marble_flow::Flow;

// player fields
static const uint8_t SLOT = 0x18, VISIBLE = 0x1c, SX = 0x1e, SY = 0x20, MASKS = 0x38;
static const uint8_t ANIM = 0x5a, SHARDS = 0x62, SHARDS_ON = 0x67;
static const uint8_t TIMER = 0x6a, TICKS = 0x6e, SCORE = 0xbc, DEATHS = 0xd2;
static const uint8_t MASK_BYTES = 30, TIMER_STOPPED = 0xff, TICKS_START = 5, OUT_OF_PLAY = 3;
static const uint32_t RNG = 0x4003a6;
static const uint16_t RNG_TICK = 0x100;
static const uint8_t FRAMES_TO_START = 6;  // marble_flow: 0x400010 race end to race start
static const uint8_t TOL = 1;              // frames: fitted intro/load counts vs MAME

static uint8_t ram[marble_physics::RAM_SIZE];

// One main loop tick as marble_sim.py main_tick: 0x400010 and the camera long are inputs,
// then 0x1344c, band spawns (before the camera store), player 0x251de, enemies, slots, rng.
static void mainTick(Mem &m, int8_t c6, int8_t c7, uint32_t camera, uint32_t frames) {
  m.wl(marble_physics::FRAMES, frames);
  marble_objects::applyQueued(m);
  const uint16_t old = m.rw(marble_physics::CAMERA);
  if ((uint16_t)camera != old) { marble_objects::cameraBands(m, old, (int16_t)camera); }
  m.wl(marble_physics::CAMERA_L, camera);
  marble_physics::tick(m, c6, c7);
  marble_enemies::update(m);
  marble_objects::update(m);
  marble_rng::rng(m, RNG_TICK);
}

// marble.cpp run_frame + logicTick of a logic frame, no input
static void logicTick(Mem &m) {
  m.wl(marble_physics::FRAMES, m.rl(marble_physics::FRAMES) + 1);
  marble_objects::applyQueued(m);
  const int16_t oldCam = m.sw(marble_physics::CAMERA);
  const uint32_t oldL = m.rl(marble_physics::CAMERA_L);
  marble_camera::tick(m);
  const int16_t newCam = m.sw(marble_physics::CAMERA);
  if (newCam != oldCam) {  // as marble.cpp: spawns before the camera store
    const uint32_t newL = m.rl(marble_physics::CAMERA_L);
    m.wl(marble_physics::CAMERA_L, oldL);
    marble_objects::cameraBands(m, oldCam, newCam);
    m.wl(marble_physics::CAMERA_L, newL);
  }
  marble_physics::tick(m, 0, 0);
  marble_enemies::update(m);
  marble_objects::update(m);
  marble_rng::rng(m, RNG_TICK);
  marble_drawlist::sort(m);
}

// marble.cpp loadRace: carry, cleared work RAM, race start, the flow's race init
static void loadRace(Flow &f) {
  const marble_flow::Carry c = marble_flow::carry(f, Mem(ram, 0));
  memset(ram, 0, sizeof(ram));
  Mem m(ram, f.race);
  marble_flow::restore(m, c);
  marble_physics::startRace(m, f.race);
  marble_flow::raceLoaded(f, m);
  marble_camera::start(m, f.race);
  marble_physics::project(m);
  marble_occlusion::enter(m, PLAYER);
}

// marble.cpp run_frame without input; returns the phase after the frame
struct Machine {
  Flow flow;
  bool odd;
  uint8_t race;
  uint16_t ticks;  // logic ticks run
  marble_hud::Tracker tracker;
  marble_video::Hud hud;
};

static marble_flow::Phase runFrame(Machine &mc, bool start) {
  Mem m(ram, mc.race);
  const marble_flow::Step step = marble_flow::frame(mc.flow, m, start);
  if (step == marble_flow::START_RACE) {
    loadRace(mc.flow);
    mc.race = mc.flow.race;
    mc.odd = true;
  }
  if (step == marble_flow::LOGIC) {
    mc.odd = !mc.odd;
    if (!mc.odd) {
      logicTick(m);
      mc.ticks++;
    }
  }
  const Mem after(ram, mc.race);
  marble_hud::update(mc.tracker, mc.flow, after, mc.hud);  // marble.cpp publish
  return marble_flow::phase(after);
}

static void newGame(Machine &mc) {
  mc = Machine{};
  marble_flow::newGame(mc.flow);
  memset(ram, 0, sizeof(ram));
  runFrame(mc, false);  // loads practice
}

static void assertNear(uint16_t want, uint16_t got, const char *what, uint8_t race) {
  char msg[96];
  snprintf(msg, sizeof(msg), "race %d %s: MAME %d, remake %d", race, what, want, got);
  TEST_ASSERT_TRUE_MESSAGE(got + TOL >= want && got <= want + TOL, msg);
}

// Practice from a new game: intro, 60 s run out (MAME: 3660 frames after the race start
// frame), 182 frames to game over, START loads practice again
static void test_time_out(void) {
  Machine mc;
  newGame(mc);
  uint16_t n = 0;
  while (runFrame(mc, false) != marble_flow::RACE && n < 1000) { n++; }
  Mem m(ram, mc.race);
  TEST_ASSERT_EQUAL_INT16(MARBLE_TIMEOUT_SECONDS, m.sw(PLAYER + TIMER));

  uint16_t k = 0;
  while (runFrame(mc, false) == marble_flow::RACE && k < 5000) { k++; }
  TEST_ASSERT_EQUAL_UINT16(MARBLE_TIMEOUT_FRAMES, k + 1);
  TEST_ASSERT_EQUAL_UINT16(marble_flow::TIME_OUT, marble_flow::phase(m));
  TEST_ASSERT_EQUAL_UINT8(2, m.rb(PLAYER + SLOT));
  TEST_ASSERT_EQUAL_UINT8(TIMER_STOPPED, m.rb(PLAYER + TICKS));

  k = 0;
  while (runFrame(mc, false) == marble_flow::TIME_OUT && k < 1000) { k++; }
  TEST_ASSERT_EQUAL_UINT16(MARBLE_TIMEOUT_GAME_OVER, k + 1);
  TEST_ASSERT_EQUAL_UINT16(marble_flow::GAME_OVER, marble_flow::phase(m));

  for (k = 0; k < 100; k++) { runFrame(mc, false); }
  TEST_ASSERT_EQUAL_UINT16(marble_flow::ATTRACT, marble_flow::phase(m));  // the title
  runFrame(mc, true);
  runFrame(mc, false);
  TEST_ASSERT_EQUAL_UINT16(marble_flow::GAME_START, marble_flow::phase(Mem(ram, mc.race)));
  TEST_ASSERT_EQUAL_UINT32(0, Mem(ram, mc.race).rl(PLAYER + SCORE));
}

// Race end of each MAME trace: the player out of play after the goal (timer stopped), then
// frame offsets (+-TOL) and values (exact) of bonus, next race intro, final bonus
// race e on, the player out of play after the goal (timer stopped), 0x400390 = 3 set by the
// logic tick of frame 0 (the race end sync frame); the HUD shows the race
static void startRaceEnd(Machine &mc, uint8_t race, int16_t seconds, uint32_t score,
                         uint16_t deaths, uint32_t frames) {
  mc = Machine{};
  mc.flow.race = race;
  mc.race = race;
  loadRace(mc.flow);
  Mem m(ram, race);
  m.ww(PLAYER + TIMER, seconds);
  m.wb(PLAYER + TICKS, TIMER_STOPPED);
  m.wl(PLAYER + SCORE, score);
  m.ww(PLAYER + DEATHS, deaths);
  m.wl(marble_physics::FRAMES, frames);
  m.wb(PLAYER + SLOT, OUT_OF_PLAY);
  mc.flow.phase = marble_flow::RACE;
  mc.flow.intro = marble_flow::NO_INTRO;
  mc.tracker.phase = marble_flow::RACE;
  mc.tracker.loaded = true;
  m.ww(marble_flow::GAME_STATE, marble_flow::RACE_END);
  marble_hud::update(mc.tracker, mc.flow, m, mc.hud);
}

static void test_race_ends(void) {
  for (const MarbleRaceEnd &e : marble_race_ends) {
    Machine mc;
    startRaceEnd(mc, e.race, e.seconds, e.score, e.deaths, e.frames);

    uint16_t next = 0, bonus = 0, init = 0, firstAdd = 0, raceOn = 0, fin = 0, finLast = 0;
    uint16_t over = 0;
    uint8_t adds = 0;
    uint32_t bonusScore = 0, finalScore = 0;
    for (uint16_t d = 1; d < 1200 && !raceOn && !over; d++) {
      Mem a(ram, mc.race);
      const uint16_t raceWord = a.rw(marble_physics::RACE), secs = a.rw(PLAYER + TIMER);
      const uint32_t score = a.rl(PLAYER + SCORE);
      const marble_flow::Phase before = marble_flow::phase(a);
      const uint8_t r0 = mc.race;
      const marble_flow::Phase now = runFrame(mc, false);
      Mem b(ram, mc.race);

      if (mc.race != r0) { init = d; continue; }
      if (b.rw(marble_physics::RACE) != raceWord && !next) { next = d; }
      if (b.rl(PLAYER + SCORE) != score && !bonus) { bonus = d; bonusScore = b.rl(PLAYER + SCORE); }
      if (init && b.rw(PLAYER + TIMER) == secs + 5) {
        if (!adds++) { firstAdd = d; }
      }
      if (init && now == marble_flow::RACE) { raceOn = d; }
      if (now == marble_flow::FINAL && before != marble_flow::FINAL) { fin = d; }
      if (now == marble_flow::FINAL && b.rl(PLAYER + SCORE) != score) {
        finLast = d;
        finalScore = b.rl(PLAYER + SCORE);
      }
      if (now == marble_flow::GAME_OVER) { over = d; }
    }

    assertNear(e.next, next, "race index", e.race);
    assertNear(e.bonus, bonus, "bonus", e.race);
    TEST_ASSERT_EQUAL_UINT32(e.bonus_score, bonusScore);
    if (e.race_on) {
      assertNear(e.init, init, "init", e.race);
      assertNear(e.first_add, firstAdd, "first +5 s", e.race);
      TEST_ASSERT_EQUAL_UINT8(e.adds, adds);
      assertNear(e.race_on, raceOn, "race start", e.race);
      Mem b(ram, mc.race);
      TEST_ASSERT_EQUAL_UINT16(e.seconds_on, b.rw(PLAYER + TIMER));
      TEST_ASSERT_EQUAL_UINT32(e.frames_on, b.rl(marble_physics::FRAMES));
      TEST_ASSERT_EQUAL_UINT8(TICKS_START, b.rb(PLAYER + TICKS));
    } else {
      assertNear(e.final, fin, "final", e.race);
      assertNear(e.final_last, finLast, "final last points", e.race);
      TEST_ASSERT_EQUAL_UINT32(e.final_score, finalScore);
      assertNear(e.game_over, over, "game over", e.race);
    }
  }
}

// crc32 of player bytes marble_carry_key, the RNG word and the slots, as marble_flow.py key_crc
static uint32_t keyCrc(const Mem &m) {
  static const uint32_t SLOTS = 0x400a9c, SLOTS_END = 0x401300;
  uint32_t crc = ~0u;
  auto add = [&crc](uint8_t v) {
    crc ^= v;
    for (uint8_t k = 0; k < 8; k++) { crc = (crc >> 1) ^ (0xedb88320u & (0u - (crc & 1))); }
  };
  for (uint8_t o : marble_carry_key) { add(m.rb(PLAYER + o)); }
  add(m.rb(RNG));
  add(m.rb(RNG + 1));
  for (uint32_t a = SLOTS; a < SLOTS_END; a++) { add(m.rb(a)); }
  return ~crc;
}

// Next race from a cleared RAM and the carried bytes (marble.cpp loadRace order) equals the
// model run that equals MAME for MARBLE_CARRY_TICKS idle ticks
static void test_carry(void) {
  for (const MarbleCarry &c : marble_carries) {
    marble_flow::Carry k = {};
    memcpy(k.timer, c.timer, sizeof(k.timer));
    k.score = c.score;
    k.deaths = c.deaths;
    k.rng = c.rng;
    k.frames = c.frames - FRAMES_TO_START;
    memset(ram, 0, sizeof(ram));
    Mem m(ram, c.race);
    marble_flow::restore(m, k);
    marble_physics::startRace(m, c.race);
    marble_physics::project(m);
    marble_occlusion::enter(m, PLAYER);
    for (uint16_t t = 0; t < MARBLE_CARRY_TICKS; t++) {
      mainTick(m, 0, 0, c.camera, m.rl(marble_physics::FRAMES) + 1);
    }
    char msg[64];
    snprintf(msg, sizeof(msg), "race %d carry run", c.race);
    TEST_ASSERT_EQUAL_HEX32_MESSAGE(c.crc, keyCrc(m), msg);
  }
}

// first field of tick t that differs, nullptr if none
static const char *diff(const Mem &m, const MarbleBonusTick &t) {
  if (marble_physics::x(m) != t.x) { return "x"; }
  if (marble_physics::y(m) != t.y) { return "y"; }
  if (marble_physics::z(m) != t.z) { return "z"; }
  if (marble_physics::state(m) != t.state) { return "state"; }
  if (m.rb(PLAYER + VISIBLE) != t.vis) { return "vis"; }
  if (m.sw(PLAYER + SX) != t.sx) { return "sx"; }
  if (m.sw(PLAYER + SY) != t.sy) { return "sy"; }
  if (m.rl(PLAYER + ANIM) != t.anim) { return "anim"; }
  if (m.rb(PLAYER + SHARDS_ON) && marble_physics::animEntry(m.rl(PLAYER + SHARDS)) != t.shard_hdr) { return "shards"; }
  if (memcmp(ram + (PLAYER + MASKS - marble_physics::RAM_BASE), t.mask, MASK_BYTES)) {
    return "mask";
  }
  if (m.rw(RNG) != t.rng) { return "rng"; }
  return nullptr;
}

// MAME segment: 0x1bbaa time bonus event, state 8 for 90 ticks (+10 s), then rolling
static void test_replay_bonus(void) {
  for (uint8_t s = 0; s < MARBLE_BONUS_SEGMENTS; s++) {
    const MarbleBonusSegment &seg = marble_bonuses_segments[s];
    memset(ram, 0, sizeof(ram));
    for (uint8_t i = 0; i < seg.nram; i++) {
      const MarbleBonusRam &r = seg.ram[i];
      memcpy(ram + (r.addr - marble_physics::RAM_BASE), r.bytes, r.len);
    }
    Mem m(ram, seg.race);
    marble_drawlist::init(m);  // the fixture has no draw list; slot inserts need one
    const int16_t s0 = m.sw(PLAYER + TIMER);

    uint16_t bonusTicks = 0;
    for (uint16_t k = 0; k < seg.nticks; k++) {
      const MarbleBonusTick &t = seg.ticks[k];
      mainTick(m, t.c6, t.c7, t.camera, t.frames);
      bonusTicks += marble_physics::state(m) == marble_physics::TIME_BONUS;
      const char *bad = diff(m, t);
      if (!bad) { continue; }

      char msg[160];
      snprintf(msg, sizeof(msg), "bonus segment %d tick %d: %s differs (state %d, expected %d)",
               s, k, bad, marble_physics::state(m), t.state);
      TEST_FAIL_MESSAGE(msg);
    }
    TEST_ASSERT_EQUAL_UINT16(90, bonusTicks);
    TEST_ASSERT_EQUAL_INT16(s0 + 10, m.sw(PLAYER + TIMER));  // the logic adds, the IRQ paused
  }
}

// expected HUD step at frame offset d (the last step at or before d)
static const MarbleHudStep &stepAt(const MarbleHudRun &r, int d) {
  uint16_t k = 0;
  while (k + 1 < r.nsteps && (int)r.steps[k + 1].at <= d) { k++; }
  return r.steps[k];
}

static bool same(const marble_video::Hud &h, const MarbleHudStep &s) {
  return h.screen == s.screen && h.pal3 == s.pal3 && h.pal11 == s.pal11 && h.add == s.add &&
         h.value == s.value;
}

// HUD of frame d equals the model at d - TOL .. d + TOL
static void checkHud(const MarbleHudRun &r, int d, const marble_video::Hud &h) {
  for (int k = -TOL; k <= TOL; k++) {
    if (same(h, stepAt(r, d + k))) { return; }
  }
  const MarbleHudStep &s = stepAt(r, d);
  char msg[160];
  snprintf(msg, sizeof(msg), "race %d frame %d: screen 0x%x pal %d/%d add %d value %d, MAME "
           "0x%x %d/%d %d %d", r.race, d, h.screen, h.pal3, h.pal11, h.add, (int)h.value,
           s.screen, s.pal3, s.pal11, s.add, (int)s.value);
  TEST_FAIL_MESSAGE(msg);
}

// new game to game over (practice time out): every frame from the race init
static void test_hud_time_out(void) {
  const MarbleHudRun &r = marble_hud_runs[0];
  TEST_ASSERT_EQUAL_UINT8(MARBLE_HUD_SYNC_INIT, r.sync);
  Machine mc;
  newGame(mc);  // frame 0: race init
  checkHud(r, 0, mc.hud);
  for (int d = 1; d < r.frames; d++) {
    runFrame(mc, false);
    checkHud(r, d, mc.hud);
  }
}

// race end of every race: bonus line and palette, level load, next intro / final screen
static void test_hud_race_ends(void) {
  for (uint8_t k = 1; k < sizeof(marble_hud_runs) / sizeof(marble_hud_runs[0]); k++) {
    const MarbleHudRun &r = marble_hud_runs[k];
    TEST_ASSERT_EQUAL_UINT8(MARBLE_HUD_SYNC_RACE_END, r.sync);
    Machine mc;
    startRaceEnd(mc, r.race, r.seconds, r.score, r.deaths, r.frames0);
    checkHud(r, 0, mc.hud);
    for (int d = 1; d < r.frames; d++) {
      runFrame(mc, false);
      checkHud(r, d, mc.hud);
    }
  }
}

// goal with 0 s left: no points, the bonus line still ends at the bonus frame (0x118d2)
static void test_hud_bonus_zero(void) {
  const MarbleHudRun &r = marble_hud_runs[1];  // practice race end
  Machine mc;
  startRaceEnd(mc, r.race, 0, r.score, r.deaths, r.frames0);
  uint16_t shown = 0, after = 0;
  for (int d = 1; d < 200 && mc.flow.race == r.race; d++) {
    runFrame(mc, false);
    if (mc.hud.screen & marble_hud::BONUS) {
      shown++;
      after = 0;
    } else if (shown) {
      after++;
    }
  }
  TEST_ASSERT_TRUE(shown > 0);
  TEST_ASSERT_TRUE_MESSAGE(after > 0, "bonus line until the next race");
  TEST_ASSERT_EQUAL_UINT32(r.score, Mem(ram, mc.race).rl(PLAYER + SCORE));
}

// after game over: PUSH 1 PLAYER START until START, then the new game's race init
// --- title (MARBLE.md "Attract") ------------------------------------------------------

static const uint32_t PART_SLOTS = 0x400a9c;
static const uint8_t PART_STRIDE = 10;
static const uint16_t TITLE_LEN = 600, TITLE_TAIL = 6;  // MAME: title end to the next segment
static const uint16_t GAME_OVER_TITLE = 14;                 // MAME: game over to title

static uint8_t parts(const Machine &mc) { return marble_particles::count(Mem(ram, mc.race)); }

// crc32 of the particle slots (marble_attract.py fwrite)
static uint32_t partsCrc(uint8_t n) {
  const uint8_t *p = ram + (PART_SLOTS - marble_physics::RAM_BASE);
  uint32_t crc = ~0u;
  for (uint16_t i = 0; i < n * PART_STRIDE; i++) {
    crc ^= p[i];
    for (uint8_t k = 0; k < 8; k++) { crc = (crc >> 1) ^ (0xedb88320u & (0u - (crc & 1))); }
  }
  return ~crc;
}

// frames until the title's particles show (0: never within limit)
static uint16_t untilTitle(Machine &mc, uint16_t limit) {
  for (uint16_t n = 1; n <= limit; n++) {
    runFrame(mc, false);
    if (parts(mc)) { return n; }
  }
  return 0;
}

static const MarblePartsRun &mameRun(const char *trace, uint32_t frame) {
  for (const MarblePartsRun &r : marble_parts_runs) {
    if (!strcmp(r.trace, trace) && r.frame == frame) { return r; }
  }
  TEST_FAIL_MESSAGE("no MAME particle run");
  return marble_parts_runs[0];
}

static void attract(Machine &mc) {
  mc = Machine{};
  memset(ram, 0, sizeof(ram));
  Mem m(ram, 0);
  marble_flow::attract(mc.flow, m);
}

// boot into the title: 3 marbles from frame 7 for 600 frames, title cells meanwhile (stage
// 0, 1, 2 on the first frames), then again after the MAME segment gap
static void test_title_boot(void) {
  Machine mc;
  attract(mc);
  TEST_ASSERT_EQUAL_UINT16(7, untilTitle(mc, 100));
  TEST_ASSERT_EQUAL_UINT8(marble_particles::TITLE_COUNT, parts(mc));
  TEST_ASSERT_EQUAL_HEX16(marble_hud::PAL | marble_hud::TITLE, mc.hud.screen);
  TEST_ASSERT_EQUAL_UINT8(0, mc.hud.stage);
  runFrame(mc, false);
  TEST_ASSERT_EQUAL_UINT8(1, mc.hud.stage);
  for (uint16_t n = 2; n < TITLE_LEN; n++) {
    runFrame(mc, false);
    TEST_ASSERT_TRUE(parts(mc) == marble_particles::TITLE_COUNT && (mc.hud.screen & marble_hud::TITLE));
  }
  runFrame(mc, false);
  TEST_ASSERT_EQUAL_UINT8(0, parts(mc));
  TEST_ASSERT_EQUAL_HEX16(0, mc.hud.screen);
  for (uint16_t n = 1; n < TITLE_TAIL; n++) { runFrame(mc, false); }
  TEST_ASSERT_EQUAL(marble_flow::NO_DEMO, mc.flow.demo);
  runFrame(mc, false);  // MAME: the next segment 6 frames after the title, a demo race
  TEST_ASSERT_EQUAL(marble_flow::DEMO_LOAD, mc.flow.demo);
  TEST_ASSERT_EQUAL_HEX16(marble_hud::BLACK, mc.hud.screen);
  TEST_ASSERT_EQUAL(marble_flow::ATTRACT, marble_flow::phase(Mem(ram, mc.race)));
}

// practice time out: game over with one rng(0x100) (the RNG stands still otherwise, as in
// MAME p0: 0x0dc3 -> 0x8739), the title 14 frames later; marbles from that RNG equal MAME's
// (test_marble_attract), here MAME p0's RNG gives its slots
static void test_gameover_to_title(void) {
  Machine mc;
  newGame(mc);
  uint16_t n = 0;
  uint16_t before = 0;
  while (runFrame(mc, false) != marble_flow::GAME_OVER && n < 5000) {
    before = Mem(ram, mc.race).rw(RNG);
    n++;
  }
  uint8_t tmp[marble_physics::RAM_SIZE] = {};
  Mem t(tmp, 0);
  t.ww(RNG, before);
  marble_rng::rng(t, 0x100);

  uint16_t rng = 0;
  for (n = 1; n <= 100 && !parts(mc); n++) {
    rng = Mem(ram, mc.race).rw(RNG);
    runFrame(mc, false);
  }
  TEST_ASSERT_EQUAL_UINT16(GAME_OVER_TITLE, n - 1);
  TEST_ASSERT_EQUAL_HEX16(t.rw(RNG), rng);

  const MarblePartsRun &run = mameRun("p0", 4586);
  Mem m(ram, mc.race);
  m.ww(RNG, run.rng);
  marble_particles::init(m, run.count, run.mode);
  for (uint16_t k = 0; k < 10; k++) {
    TEST_ASSERT_EQUAL_HEX32(run.crc[k], partsCrc(run.count));
    runFrame(mc, false);
  }
}

// final screen: 28 marbles (palette fill, then init) 3 frames after 0x400390 = 6 from that
// frame's RNG (MAME g5 frame 1422), cleared at game over, then the title
static void test_final_to_title(void) {
  Machine mc = {};
  memset(ram, 0, sizeof(ram));
  mc.race = 5;
  Mem m(ram, mc.race);
  const MarblePartsRun &run = mameRun("g5", 1422);
  m.ww(RNG, run.rng);
  m.ww(marble_flow::GAME_STATE, marble_flow::FINAL);
  m.wb(PLAYER + TICKS, TIMER_STOPPED);  // the race end stopped the timer
  mc.flow.phase = marble_flow::FINAL;
  mc.flow.intro = marble_flow::NO_INTRO;
  mc.flow.final = 1000;
  for (uint8_t k = 0; k < 3; k++) { runFrame(mc, false); }
  TEST_ASSERT_EQUAL_UINT8(marble_particles::FINAL_COUNT, parts(mc));
  for (uint16_t k = 0; k < 20; k++) {
    TEST_ASSERT_EQUAL_HEX32(run.crc[k], partsCrc(run.count));
    runFrame(mc, false);
  }
  uint16_t n = 0;
  while (runFrame(mc, false) != marble_flow::GAME_OVER && n < 2000) { n++; }
  TEST_ASSERT_EQUAL_UINT8(0, parts(mc));
  TEST_ASSERT_EQUAL_UINT16(GAME_OVER_TITLE, untilTitle(mc, 100));
  TEST_ASSERT_EQUAL_UINT8(marble_particles::TITLE_COUNT, parts(mc));
}

// START on the first, a middle and the last title frame: a clean practice race follows
static void test_title_start_clean(void) {
  static const uint16_t AT[] = {1, 300, TITLE_LEN};
  for (uint16_t at : AT) {
    Machine mc;
    attract(mc);
    untilTitle(mc, 100);
    for (uint16_t k = 1; k < at; k++) { runFrame(mc, false); }
    runFrame(mc, true);
    runFrame(mc, false);  // loads practice
    TEST_ASSERT_EQUAL(marble_flow::GAME_START, marble_flow::phase(Mem(ram, mc.race)));
    TEST_ASSERT_EQUAL_UINT8(0, parts(mc));
    TEST_ASSERT_FALSE(mc.hud.screen & marble_hud::TITLE);
    TEST_ASSERT_EQUAL_UINT32(0, Mem(ram, mc.race).rl(PLAYER + SCORE));
  }
}

// title, START, time out, title: three times, the same title each time
static void test_title_cycles(void) {
  Machine mc;
  attract(mc);
  for (uint8_t cycle = 0; cycle < 3; cycle++) {
    TEST_ASSERT_TRUE(untilTitle(mc, 100) > 0);
    runFrame(mc, true);
    uint16_t n = 0;
    while (runFrame(mc, false) != marble_flow::GAME_OVER && n < 5000) { n++; }
    TEST_ASSERT_TRUE(n < 5000);
    TEST_ASSERT_EQUAL_UINT16(GAME_OVER_TITLE, untilTitle(mc, 100));
    TEST_ASSERT_EQUAL_UINT8(marble_particles::TITLE_COUNT, parts(mc));
  }
}
static marble_sound::Sound flowSound;

// a race load requests the race's song; the time out of a new game plays the 0x3f jingle
static void test_race_music(void) {
  for (uint8_t race = 0; race < 6; race++) {
    Flow f = {};
    f.race = race;
    marble_sound::reset(flowSound);
    loadRace(f);
    marble_sound::step(flowSound);
    TEST_ASSERT_EQUAL_MESSAGE(race + 1, flowSound.music & 0xff, "race music");
  }
  Machine mc;
  marble_sound::reset(flowSound);
  newGame(mc);
  marble_sound::step(flowSound);
  TEST_ASSERT_EQUAL(1, flowSound.music & 0xff);
  uint16_t k = 0;
  while (runFrame(mc, false) != marble_flow::TIME_OUT && k < 6000) {
    marble_sound::step(flowSound);
    k++;
  }
  marble_sound::step(flowSound);
  TEST_ASSERT_EQUAL(MARBLE_SONG_3F, flowSound.music & 0xff);
}

// the logic's sound sites reach the sound board: a breaking marble sends 0x38
static void test_break_sound(void) {
  Flow f = {};
  marble_sound::reset(flowSound);
  loadRace(f);
  marble_sound::step(flowSound);
  Mem m(ram, 0);
  marble_physics::enterState(m, PLAYER, marble_physics::BROKEN);
  uint8_t cmds[marble_sound::QUEUE];
  const uint8_t n = marble_sound::step(flowSound, cmds);
  TEST_ASSERT_EQUAL(1, n);
  TEST_ASSERT_EQUAL_HEX8(marble_sound::SND_BREAK, cmds[0]);
}

// --- attract demo race (MARBLE.md "Demo race") ------------------------------------------

static const uint32_t WAYPOINT = 0x400446;
static const uint32_t PRACTICE_WAYPOINTS = 0x2419e;
static const uint8_t BANNER_FRAMES = 90;

struct DemoRun {
  const MarbleDemoTick *ticks;
  uint16_t n;
  const MarbleDemoBanner *banners;
  uint8_t nbanners;
  uint16_t rng;
};
static const DemoRun DEMO_RUNS[2] = {
    {MARBLE_DEMO0_TICKS, sizeof(MARBLE_DEMO0_TICKS) / sizeof(MarbleDemoTick), MARBLE_DEMO0_BANNERS,
     sizeof(MARBLE_DEMO0_BANNERS) / sizeof(MarbleDemoBanner), MARBLE_DEMO0_RNG},
    {MARBLE_DEMO1_TICKS, sizeof(MARBLE_DEMO1_TICKS) / sizeof(MarbleDemoTick), MARBLE_DEMO1_BANNERS,
     sizeof(MARBLE_DEMO1_BANNERS) / sizeof(MarbleDemoBanner), MARBLE_DEMO1_RNG},
};

static uint32_t demoKeyCrc(void) {
  uint32_t crc = ~0u;
  for (uint8_t k : MARBLE_DEMO_KEY) {
    crc ^= ram[PLAYER - marble_physics::RAM_BASE + k];
    for (uint8_t b = 0; b < 8; b++) { crc = (crc >> 1) ^ (0xedb88320u & (0u - (crc & 1))); }
  }
  return ~crc;
}

// frames until the flow's demo part is d (0: not within limit)
static uint16_t untilDemo(Machine &mc, marble_flow::Demo d, uint16_t limit) {
  for (uint16_t n = 1; n <= limit; n++) {
    runFrame(mc, false);
    if (mc.flow.demo == d) { return n; }
  }
  return 0;
}

// one demo race from its segment start (DEMO_LOAD) against the MAME demo of the race: load
// and intro frames, per tick the player, cursor and RNG, banners for 90 frames, the title
// 11 frames after the waypoint list end
static void checkDemo(Machine &mc, uint8_t race) {
  const DemoRun &r = DEMO_RUNS[race];
  char msg[64];
  TEST_ASSERT_EQUAL_UINT8(race, mc.flow.race);
  for (uint16_t n = 1; n < MARBLE_DEMO_LOAD[race]; n++) {
    runFrame(mc, false);
    TEST_ASSERT_EQUAL_HEX16(marble_hud::BLACK, mc.hud.screen);
  }
  Mem(ram, mc.race).ww(RNG, r.rng);  // MAME's RNG at the race init: equal ticks
  runFrame(mc, false);
  TEST_ASSERT_EQUAL(marble_flow::DEMO_INTRO, mc.flow.demo);
  TEST_ASSERT_EQUAL_UINT8(race, mc.race);
  TEST_ASSERT_EQUAL(marble_flow::ATTRACT, marble_flow::phase(Mem(ram, mc.race)));

  mc.ticks = 0;
  TEST_ASSERT_EQUAL_UINT16(MARBLE_DEMO_START[race], untilDemo(mc, marble_flow::DEMO_RUN, 10));
  TEST_ASSERT_EQUAL_UINT16(1, mc.ticks);
  TEST_ASSERT_EQUAL_INT16(60, Mem(ram, mc.race).sw(PLAYER + TIMER));
  static uint8_t shown[2000];  // HUD banner per frame since the first tick
  static uint16_t tickFrame[600];
  uint16_t frame = 0;
  for (uint16_t k = 0;;) {
    const Mem m(ram, mc.race);
    const MarbleDemoTick &t = r.ticks[k];
    snprintf(msg, sizeof(msg), "race %u tick %u", race, k);
    TEST_ASSERT_EQUAL_HEX16_MESSAGE(t.x, m.rw(PLAYER + 0x0c), msg);
    TEST_ASSERT_EQUAL_HEX16_MESSAGE(t.y, m.rw(PLAYER + 0x10), msg);
    TEST_ASSERT_EQUAL_UINT8_MESSAGE(t.state, m.rb(PLAYER + 0x1a), msg);
    TEST_ASSERT_EQUAL_HEX16_MESSAGE(t.cursor, m.rl(WAYPOINT) & 0xffff, msg);
    TEST_ASSERT_EQUAL_HEX16_MESSAGE(t.rng, m.rw(RNG), msg);
    TEST_ASSERT_EQUAL_HEX32_MESSAGE(t.crc, demoKeyCrc(), msg);
    TEST_ASSERT_EQUAL_HEX16_MESSAGE(marble_hud::PAL | marble_hud::TOP | marble_hud::DEMO,
                                    mc.hud.screen, msg);
    tickFrame[k] = frame;
    shown[frame] = mc.hud.banner;
    if (++k == r.n) { break; }

    const uint16_t ticks = mc.ticks;
    while (mc.ticks == ticks) {
      runFrame(mc, false);
      shown[++frame] = mc.hud.banner;
    }
  }

  // each banner from its tick for 90 frames (the last one until the demo ends), then none
  for (uint8_t b = 0; b < r.nbanners; b++) {
    const uint16_t from = tickFrame[r.banners[b].tick];
    snprintf(msg, sizeof(msg), "race %u banner %u", race, b);
    for (uint16_t f = from; f < from + BANNER_FRAMES && f <= frame; f++) {
      TEST_ASSERT_EQUAL_UINT8_MESSAGE(r.banners[b].banner, shown[f], msg);
    }
    if (from + BANNER_FRAMES <= frame) {
      TEST_ASSERT_EQUAL_UINT8_MESSAGE(marble_video::NO_BANNER, shown[from + BANNER_FRAMES], msg);
    }
  }
  TEST_ASSERT_EQUAL_UINT16(MARBLE_DEMO_TITLE_AFTER_END, untilTitle(mc, 100));
  TEST_ASSERT_EQUAL_UINT16(r.n, mc.ticks);  // no ticks after the list end
}

// title, practice demo, title, beginner demo, title, practice demo
static void test_demo_races(void) {
  Machine mc;
  attract(mc);
  for (uint8_t k = 0; k < 3; k++) {
    TEST_ASSERT_TRUE(untilDemo(mc, marble_flow::DEMO_LOAD, 1000) > 0);
    checkDemo(mc, k & 1);
  }
}

// START in the level load, the intro, the race and after the waypoint list end: a clean
// practice race with its music
static void test_demo_start_clean(void) {
  static const marble_flow::Demo PART[] = {marble_flow::DEMO_LOAD, marble_flow::DEMO_INTRO,
                                           marble_flow::DEMO_RUN, marble_flow::DEMO_RUN,
                                           marble_flow::DEMO_END};
  static const uint16_t AFTER[] = {10, 1, 1, 300, 2};
  for (uint8_t k = 0; k < sizeof(PART) / sizeof(PART[0]); k++) {
    Machine mc;
    attract(mc);
    for (uint8_t d = 0; d <= 1; d++) {  // the beginner demo: its race is left over
      TEST_ASSERT_TRUE(untilDemo(mc, marble_flow::DEMO_LOAD, 1000) > 0);
      if (d == 0) { TEST_ASSERT_TRUE(untilDemo(mc, marble_flow::NO_DEMO, 2000) > 0); }
    }
    TEST_ASSERT_TRUE(untilDemo(mc, PART[k], 2000) > 0);
    for (uint16_t n = 1; n < AFTER[k]; n++) { runFrame(mc, false); }
    marble_sound::step(flowSound);
    runFrame(mc, true);
    runFrame(mc, false);  // loads practice
    const Mem m(ram, mc.race);
    TEST_ASSERT_EQUAL(marble_flow::GAME_START, marble_flow::phase(m));
    TEST_ASSERT_EQUAL_UINT8(0, mc.race);
    TEST_ASSERT_EQUAL(marble_flow::NO_DEMO, mc.flow.demo);
    TEST_ASSERT_EQUAL_UINT32(0, m.rl(PLAYER + SCORE));
    TEST_ASSERT_EQUAL_UINT32(0, m.rl(marble_physics::MSG_CHAIN));
    TEST_ASSERT_FALSE(mc.hud.screen & (marble_hud::DEMO | marble_hud::BLACK));
    marble_sound::step(flowSound);
    TEST_ASSERT_EQUAL(1, flowSound.music & 0xff);  // practice music
  }
}

// the waypoint driver needs 0x400390 = 1: a race with a cursor set rolls as without
static void test_demo_gate(void) {
  Machine mc;
  newGame(mc);
  while (runFrame(mc, false) != marble_flow::RACE) {}
  static uint8_t start[marble_physics::RAM_SIZE];
  memcpy(start, ram, sizeof(ram));
  const Machine at = mc;
  for (uint16_t n = 0; n < 200; n++) { runFrame(mc, false); }
  const uint32_t want = demoKeyCrc();

  memcpy(ram, start, sizeof(ram));
  mc = at;
  Mem(ram, mc.race).wl(WAYPOINT, PRACTICE_WAYPOINTS);
  for (uint16_t n = 0; n < 200; n++) { runFrame(mc, false); }
  TEST_ASSERT_EQUAL_HEX32(want, demoKeyCrc());
  TEST_ASSERT_EQUAL_HEX32(PRACTICE_WAYPOINTS, Mem(ram, mc.race).rl(WAYPOINT));
}

// attract sends no sound: title and a whole demo race
static void test_demo_silent(void) {
  Machine mc;
  attract(mc);
  marble_sound::step(flowSound);
  TEST_ASSERT_TRUE(untilDemo(mc, marble_flow::DEMO_LOAD, 1000) > 0);
  TEST_ASSERT_TRUE(untilDemo(mc, marble_flow::NO_DEMO, 2000) > 0);
  TEST_ASSERT_EQUAL_UINT8(0, marble_sound::queued());
}

